# unityHPC/job_template.sh (ml) — generated by /unity-hpc:connect. Do not hand-edit.
# Multi-node capable training via torchrun. run.sh emits the #SBATCH header above
# this and exports EXP, REMOTE_DIR, CAMPAIGN, REMOTE_RESULTS_DIR and JOB_COMMAND.
set -euo pipefail

REMOTE_DIR="${REMOTE_DIR/#\~/$HOME}"
cd "$REMOTE_DIR"

# Where this job's artifacts belong. `run.sh fetch` prefers this same path when
# it exists on the cluster, so a job that writes here is pulled one campaign at
# a time instead of dragging every earlier campaign along. Exported but NOT
# created: an empty directory here would satisfy fetch's prefer-if-present
# probe for a job that in fact writes a flat _results/, and fetch would then
# pull nothing.
export RESULTS_DIR="${REMOTE_RESULTS_DIR:-${REMOTE_DIR}/_results}/${CAMPAIGN}"

export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True

set +u
[[ -f /usr/share/lmod/lmod/init/bash ]] && . /usr/share/lmod/lmod/init/bash
set -u
if [ -n "${MODULES:-}" ]; then
    module purge && module load ${MODULES}
fi

# An optional unityHPC/bootstrap.sh replaces the VENV_PATH activate below.
# Sourced (not run in a subshell) so a hook that activates a venv or exports
# HF_HOME etc. affects this job. Serialised with flock on REMOTE_DIR so N
# fan-out tasks starting together do not race a venv build on shared NFS.
# The re-check after acquiring the lock is `if/then`, never `[ ... ] &&`: under
# `set -e` a false `&&` guard is itself a failing command and aborts the very
# path meant to handle "the hook exists."
if [ -f "unityHPC/bootstrap.sh" ]; then
    exec 9>"${REMOTE_DIR}/.unity_bootstrap.lock"
    flock 9
    if [ -f "unityHPC/bootstrap.sh" ]; then
        . "unityHPC/bootstrap.sh"
    fi
    flock -u 9
    exec 9>&-
else
    if [ -n "${VENV_PATH:-}" ] && [ -f "${VENV_PATH}/bin/activate" ]; then
        . "${VENV_PATH}/bin/activate"
    fi
fi

# Not `... | head -1 || echo unknown`: on a CPU node nvidia-smi writes
# "No devices were found" to STDOUT and exits non-zero, so under `set -o
# pipefail` head emits that text AND the fallback fires, and the banner ends up
# split over two lines with the error in the middle of it. Ask separately, then
# default.
GPU_NAME=""
if command -v nvidia-smi >/dev/null 2>&1; then
    GPU_NAME=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | head -1 || true)
fi
case "$GPU_NAME" in ""|*"No devices"*) GPU_NAME="unknown" ;; esac
NODES="${SLURM_NNODES:-1}"
echo "=== $(date -u +%Y-%m-%dT%H:%M:%SZ) | exp=${EXP} | nodes=${NODES} | gpu=${GPU_NAME} ==="

run_training() {
    if [ "$NODES" -gt 1 ]; then
        export NCCL_DEBUG=INFO
        MASTER_ADDR=$(scontrol show hostnames "$SLURM_JOB_NODELIST" | head -1)
        export MASTER_ADDR
        export MASTER_PORT="${MASTER_PORT:-29500}"
        torchrun \
            --nnodes="$NODES" \
            --nproc_per_node="${SLURM_GPUS_ON_NODE:-1}" \
            --rdzv_backend=c10d \
            --rdzv_endpoint="${MASTER_ADDR}:${MASTER_PORT}" \
            --node_rank="${SLURM_NODEID:-0}" \
            ${JOB_COMMAND}
    else
        eval "$JOB_COMMAND"
    fi
}

set +e
run_training &
TRAIN_PID=$!
SAMPLER_PID=""
if [ "${GPU_SAMPLE_INTERVAL:-0}" -gt 0 ] && command -v nvidia-smi >/dev/null 2>&1; then
    SAMPLE_FILE="${GPU_SAMPLE_FILE:-${RESULTS_DIR}/${EXP}-${SLURM_JOB_ID}.gpu.csv}"
    mkdir -p "$(dirname "$SAMPLE_FILE")"
    printf 'timestamp_utc,gpu_index,utilization_gpu,memory_used,memory_total,power_draw,temperature_gpu\n' >"$SAMPLE_FILE"
    (
        while kill -0 "$TRAIN_PID" 2>/dev/null; do
            timestamp="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
            nvidia-smi --query-gpu=index,utilization.gpu,memory.used,memory.total,power.draw,temperature.gpu \
                --format=csv,noheader,nounits 2>/dev/null \
                | sed "s/^/${timestamp},/" >>"$SAMPLE_FILE" || true
            sleep "$GPU_SAMPLE_INTERVAL"
        done
    ) &
    SAMPLER_PID=$!
fi
wait "$TRAIN_PID"
RC=$?
if [ -n "$SAMPLER_PID" ]; then
    kill "$SAMPLER_PID" 2>/dev/null || true
    wait "$SAMPLER_PID" 2>/dev/null || true
fi
set -e
echo "=== done $(date -u +%Y-%m-%dT%H:%M:%SZ) rc=${RC} ==="
exit "$RC"
